from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            edge = False
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    edge = True
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            if not edge:
                color = 2 if len(comp) % 2 == 0 else 7
                for y, x in comp:
                    out[y][x] = color
    return out

